    'faq' => '❓ Частые вопросы',
    'faqDesc' => ' 
 💡 Часто задаваемые вопросы ⁉️

1️⃣ У вашего VPN статический IP? Могу ли я использовать его для криптовалютных бирж?

✅ Из-за ситуации с интернетом и ограничений в стране наш сервис не подходит для трейдинга и имеет только статическую локацию.

2️⃣ Если я продлю аккаунт до его истечения, сгорят ли оставшиеся дни?

✅ Нет, оставшиеся дни аккаунта учитываются при продлении, и если, например, вы продлите свой месячный аккаунт за 5 дней до истечения, вы получите 5 оставшихся дней + 30 дней продления.

3️⃣ Что произойдёт, если мы подключимся к одному аккаунту больше разрешённого лимита?

✅ В этом случае объём вашего сервиса быстро закончится.

4️⃣ Какого типа ваш VPN?

✅ Наши VPN — это v2ray, и мы поддерживаем различные протоколы, чтобы даже в периоды сбоев интернета вы могли пользоваться сервисом без проблем и падения скорости.

5️⃣ Из какой страны VPN?

✅ Наш VPN-сервер находится в Германии

6️⃣ Как мне пользоваться этим VPN?

✅ Для инструкции по использованию приложения нажмите кнопку «📚 Инструкция».

7️⃣ VPN не подключается, что делать?

✅ Обратитесь в поддержку вместе с изображением сообщения об ошибке, которое вы получаете.

8️⃣ Гарантируется ли, что ваш VPN всегда подключается?

✅ Из-за непредсказуемости интернета в стране дать гарантию невозможно; мы можем лишь гарантировать, что приложим все усилия для предоставления наилучшего сервиса.

9️⃣ Есть ли возврат средств?

